mapper.select:
SELECT id, imageHash, modelVersion, weightSha256, preprocessVersion, predictedLabel, probability,
       calibratedProbability, description, reliabilityScore, topPredictions, qualityScore,
       qualityReasons, isOod, oodScore, rejected, abstainReason, requiresReview, createTime
FROM t_inference_cache
WHERE imageHash = #{imageHash}
  AND modelVersion = #{modelVersion}
  AND weightSha256 = #{weightSha256}
  AND preprocessVersion = #{preprocessVersion}
LIMIT 1
